          // and a new daemon will be created shorly
        });
      });

      // will be executed when dead
      watch.once('dead', function () {
        if (ignoreDeath) return;

        // kill child process
        daemonInRestart = true;
        child.kill();

        // when the child is dead start a new daemon
        child.once('stop', function () {
